return {api_version=1,id="EX1_303",name="Shadowflame",text="Destroy a friendly minion and deal its Attack damage to all enemy minions.",set="EXPERT1",type="spell",class="warlock",rarity="rare",spell_school="shadow",cost=4,target_mode="required",targets=function(ctx,self)return ctx:friendly_minions(self)end,on_play=function(ctx,self,target)local amount=math.max(0,ctx:entity(target).attack);ctx:destroy(target);ctx:damage_all(ctx:enemy_minions(self),amount)end}
